fn greater(a: Vec<i8>, b: Vec<i8>) -> Vec<bool> {
    // Ensure both arrays have the same length
    assert_eq!(a.len(), b.len(), "Input arrays must have the same length");

    // Create a result vector to store the boolean results
    let mut result = Vec::with_capacity(a.len());

    // Iterate through both arrays and compare elements
    for i in 0..a.len() {
        // Compare the elements after converting to i32
        result.push(a[i] as i32 > b[i] as i32);
    }

    result
}